import{_ as a,a0 as p,w as o,s as d,ao as r,I as t,x as l,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"完善的 API 的 4 个基本特征 | LCTT x X-CMD","titleTemplate":false,"description":"完善的 API 的 4 个基本特征 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完善的 API 的 4 个基本特征 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完善的 API 的 4 个基本特征 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 4 essential characteristics of successful APIs","title":"完善的 API 的 4 个基本特征","tag":"202106","desc":""},"relativePath":"202106/20210518 4 essential characteristics of successful APIs.md","filePath":"[post].md"}'),u={name:"202106/20210518 4 essential characteristics of successful APIs.md"};function P(f,s,A,m,I,T){const n=p("Link");return o(),d("div",null,[s[60]||(s[60]=r('<h1 id="完善的-api-的-4-个基本特征" tabindex="-1">完善的 API 的 4 个基本特征 <a class="header-anchor" href="#完善的-api-的-4-个基本特征" aria-label="Permalink to “完善的 API 的 4 个基本特征”">​</a></h1><blockquote><p>创建一个 API（应用程序接口），我们所要做的远远不止是让它能“正常工作”。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/14/155547zs3mffismifqqi59.jpg" alt=""></p><p>如果你正在构建基于 C/S 模型的应用程序，那么你需要一个应用程序接口（API）。API 就是一种非常清晰而又明确的定义，它是一个<ruby>进程<rt>process</rt></ruby>与另一个进程之间明确定义的边界。Web 应用中我们常见的边界定义就是 REST/JSON API。</p><p>虽然很多开发者可能主要关注在如何让 API 正常工作（或功能正常），但却还有一些“非功能性”的要求也是需要他们注意的。所有的 API <em>必须具备</em> 的 4 个非功能性的要求是：</p><ul><li>安全</li><li>文档</li><li>验证</li><li>测试</li></ul><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>在软件开发中，安全是最基本的要求。对于 API 开发者来说，API 的安全性主要包含以下 4 个方面：</p><ol><li>HTTPS/SSL 证书</li><li>跨域资源共享</li><li>身份认证与 JSON Web 令牌</li><li>授权与作用域</li></ol><h4 id="_1、https-ssl-证书" tabindex="-1">1、HTTPS/SSL 证书 <a class="header-anchor" href="#_1、https-ssl-证书" aria-label="Permalink to “1、HTTPS/SSL 证书”">​</a></h4>',10)),t("p",null,[s[1]||(s[1]=l("Web 应用的黄金标准是使用 SSL 证书的 HTTPS 协议。",-1)),e(n,{href:"https://letsencrypt.org/"},{default:i(()=>[...s[0]||(s[0]=[l("Let's Encrypt",-1)])]),_:1}),s[2]||(s[2]=l(" 可以帮你达到这一目的。Let's Encrypt 来自于非营利性的互联网安全研究小组（ISRG），它是一个免费的、自动化的、开放的证书颁发机构。",-1))]),s[61]||(s[61]=t("p",null,"Let's Encrypt 的软件会为你的域（LCTT 译注：包含域名、IP 等信息）生成中央授权证书。而正是这些证书确保了从你的 API 到客户端的数据载荷是点对点加密的。",-1)),t("p",null,[s[4]||(s[4]=l("Let's Encrypt 支持证书管理的多种部署方案。我们可以通过查看 ",-1)),e(n,{href:"https://letsencrypt.org/docs/"},{default:i(()=>[...s[3]||(s[3]=[l("文档",-1)])]),_:1}),s[5]||(s[5]=l(" 来找出最适合自己需要的方案。",-1))]),s[62]||(s[62]=t("h4",{id:"_2、跨域资源共享",tabindex:"-1"},[l("2、跨域资源共享 "),t("a",{class:"header-anchor",href:"#_2、跨域资源共享","aria-label":"Permalink to “2、跨域资源共享”"},"​")],-1)),s[63]||(s[63]=t("p",null,[t("ruby",null,[l("跨域资源共享"),t("rt",null,"Cross-origin resource sharing")]),l("（CORS）是一个针对浏览器的安全策略预检。如果你的 API 服务器与发出请求的客户端不在同一个域中，那么你就要处理 CORS。例如，如果你的服务器运行在 "),t("code",null,"api.domain-a.com"),l(" 并且接到一个来自 "),t("code",null,"domain-b.com"),l(" 的客户端的请求，那么 CORS 就会（让浏览器）发送一个 HTTP 预检请求，以便查看你的 API 服务是否会接受来自此客户域的客户端请求。")],-1)),t("p",null,[e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"},{default:i(()=>[...s[6]||(s[6]=[l("来自 MDN 的定义",-1)])]),_:1}),s[7]||(s[7]=l("：",-1))]),s[64]||(s[64]=t("blockquote",null,[t("p",null,"“跨域资源共享（CORS）是一种基于 HTTP 头的机制，这种机制允许服务器标记除自身源外的其他任何来源（域、方案或端口）。而对于这些被服务器标识的源，浏览器应该允许我们从它们加载资源。”")],-1)),s[65]||(s[65]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/uploads/cors_principle_1.png",alt:"CORS 原理",title:"CORS principles"})],-1)),t("p",null,[t("em",null,[s[10]||(s[10]=l("(",-1)),e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"},{default:i(()=>[...s[8]||(s[8]=[l("MDN文档",-1)])]),_:1}),s[11]||(s[11]=l("， ",-1)),e(n,{href:"https://creativecommons.org/licenses/by-sa/2.5/"},{default:i(()=>[...s[9]||(s[9]=[l("CC-BY-SA 2.5",-1)])]),_:1}),s[12]||(s[12]=l(")",-1))])]),t("p",null,[s[15]||(s[15]=l("另外，有很多用于 ",-1)),e(n,{href:"https://nodejs.org"},{default:i(()=>[...s[13]||(s[13]=[l("Node.js",-1)])]),_:1}),s[16]||(s[16]=l(" 的辅助库来 ",-1)),e(n,{href:"https://www.npmjs.com/search?q=CORS"},{default:i(()=>[...s[14]||(s[14]=[l("帮助 API 开发者处理 CORS",-1)])]),_:1}),s[17]||(s[17]=l("。",-1))]),s[66]||(s[66]=t("h4",{id:"_3、身份认证与-json-web-令牌",tabindex:"-1"},[l("3、身份认证与 JSON Web 令牌 "),t("a",{class:"header-anchor",href:"#_3、身份认证与-json-web-令牌","aria-label":"Permalink to “3、身份认证与 JSON Web 令牌”"},"​")],-1)),s[67]||(s[67]=t("p",null,"有多种方法可以验证你的 API 中的认证用户，但最好的方法之一是使用 JSON Web 令牌（JWT），而这些令牌使用各种知名的加密库进行签名。",-1)),s[68]||(s[68]=t("p",null,"当客户端登录时，身份管理服务会向客户端提供一个 JWT。然后，客户端可以使用这个令牌向 API 发出请求，API 收到请求后，从服务器读取公钥或私密信息来验证这个令牌。",-1)),t("p",null,[s[20]||(s[20]=l("有一些现有的库，可以帮助我们对令牌进行验证，包括 ",-1)),e(n,{href:"https://github.com/auth0/node-jsonwebtoken"},{default:i(()=>[...s[18]||(s[18]=[l("jsonwebtoken",-1)])]),_:1}),s[21]||(s[21]=l("。关于 JWT 的更多信息，以及各种语言中对其的支持库，请查看 ",-1)),e(n,{href:"https://jwt.io"},{default:i(()=>[...s[19]||(s[19]=[l("JWT.io",-1)])]),_:1}),s[22]||(s[22]=l("。",-1))]),s[69]||(s[69]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import jwt from &#39;jsonwebtoken&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export default function (req, res, next) {</span></span>
<span class="line"><span>    // req.headers.authorization Bearer token</span></span>
<span class="line"><span>    const token = extractToken(req)</span></span>
<span class="line"><span>    jwt.verify(token, SECRET, { algorithms: [&#39;HS256&#39;] }, (err, decoded) =&gt; {</span></span>
<span class="line"><span>        if (err) { next(err) }</span></span>
<span class="line"><span>        req.session = decoded</span></span>
<span class="line"><span>        next()</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="_4、授权与作用域" tabindex="-1">4、授权与作用域 <a class="header-anchor" href="#_4、授权与作用域" aria-label="Permalink to “4、授权与作用域”">​</a></h4><p>认证（或身份验证）很重要，但授权同样很重要。也就是说，经过验证的客户端是否有权限让服务器执行某个请求呢？这就是作用域的价值所在。当身份管理服务器对客户端进行身份认证，且创建 JWT 令牌时，身份管理服务会给当前客户提供一个作用域，这个作用域将会决定当前经过验证的客户的 API 请求能否被服务器执行。这样也就免去了服务器对访问控制列表的一些不必要的查询。</p><p>作用域是一个文本块（通常以空格分隔），用于描述一个 API 端点的访问能力。一般来说，作用域被分为资源与动作。这种模式对 REST/JSON API 很有效，因为它们有相似的 <code>RESOURCE:ACTION</code> 结构。（例如，<code>ARTICLE:WRITE</code> 或 <code>ARTICLE:READ</code>，其中 <code>ARTICLE</code> 是资源，<code>READ</code> 和 <code>WRITE</code> 是动作）。</p><p>作用域的划分让我们的 API 能够专注于功能的实现，而不是去考虑各种角色和用户。身份访问管理服务可以将不同的角色和用户分配不同的权限范围，然后再将这些不同的作用域提供给不同的 JWT 验证中的客户。</p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h4><p>当我们开发和部署 API 时，安全应该一直是最重要的要求之一。虽然安全性是一个比较宽泛的话题，但如果能解决上面四个方面的问题，这对于你的 API 来说，在生产环境中将会表现得更好。</p><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h3><p><em>有什么能比没有文档更糟糕？过期的文档。</em></p><p>开发者对文档真的是又爱又恨。尽管如此，文档仍然是 API 定义是否完善的一个关键部分。开发者需要从文档中知道如何使用这些 API，且你创建的文档对于开发者如何更好地使用 API 也有着非常巨大的作用。</p><p>创建 API 文档，我们需要关注下面三个方面：</p><ol><li>开发者入门文档（自述文件/基本介绍）</li><li>技术参考（规范/说明书）</li><li>使用方法（入门和其他指南）</li></ol><h4 id="_1、入门文档" tabindex="-1">1、入门文档 <a class="header-anchor" href="#_1、入门文档" aria-label="Permalink to “1、入门文档”">​</a></h4><p>在构建 API 服务的时候，你需要明确一些事情，比如：这个 API 是做什么的？如何建立开发者环境？如何测试该服务？如何提交问题？如何部署它？</p><p>通常我们可以通过自述（<code>README</code>）文件来回答上面的这些问题，自述文件一般放在你的代码库中，用于为开发者提供使用你项目的最基本的起点和说明。</p><p>自述文件应该包含：</p><ul><li>API 的描述</li><li>技术参考与指南的链接</li><li>如何以开发者的身份设置你的项目</li><li>如何测试这个项目</li><li>如何部署这个项目</li><li>依赖管理</li><li>代码贡献指南</li><li>行为准则</li><li>许可证</li><li>致谢</li></ul><p>你的自述文件应该简明扼要；你不必解释每一个方面，但要提供足够的信息，以便开发者在熟悉你的项目后可以进一步深入研究。</p><h4 id="_2、技术参考" tabindex="-1">2、技术参考 <a class="header-anchor" href="#_2、技术参考" aria-label="Permalink to “2、技术参考”">​</a></h4><p>在 REST/JSON API 中, 每一个具体的<ruby>端点<rt>endpoint</rt></ruby>都对应一个特定的功能，都需要一个具体的说明文档，这非常重要。文档中会定义 API 的描述，输入和可能的输出，并为各种客户端提供使用示例。</p>`,20)),t("p",null,[e(n,{href:"https://spec.openapis.org/oas/v3.1.0"},{default:i(()=>[...s[23]||(s[23]=[l("OpenAPI",-1)])]),_:1}),s[24]||(s[24]=l(" 是一个创建 REST/JSON 文档的标准, 它可以指导你完成编写 API 文档所需的各种细节。OpenAPI 还可以为你的 API 生成演示文档。",-1))]),s[70]||(s[70]=r('<h4 id="_3、使用方法" tabindex="-1">3、使用方法 <a class="header-anchor" href="#_3、使用方法" aria-label="Permalink to “3、使用方法”">​</a></h4><p>对于 API 的用户来说，仅仅只有技术说明是不够的。他们还需要知道如何在一些特定的情况和场景下来使用这些 API，而大多数的潜在用户可能希望通过你的 API 来解决他们所遇到的问题。</p><p>向用户介绍 API 的一个好的方法是利用一个“开始”页面。“开始”页面可以通过一个简单的用例引导用户，让他们迅速了解你的 API 能给他们能带来的益处。</p><h4 id="总结-1" tabindex="-1">总结 <a class="header-anchor" href="#总结-1" aria-label="Permalink to “总结”">​</a></h4><p>对于任何完善的 API，文档都是一个很关键的组成部分。当你在创建文档时，你需要关注 API 文档中的如何入门、技术参考以及如何快速开始等三个方面，这样你的 API 才算是一个完善的 API。</p><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to “验证”">​</a></h3><p>API 开发过程中经常被忽视的一个点就是验证。它是一个验证来自外部来源的输入的过程。这些来源可以是客户端发送过来的 JSON 数据，或者是你请求别人的服务收到的响应数据。我们不仅仅要检查这些数据的类型，还要确保这些数据确实是我们要的数据，这样可以消除很多潜在的问题。了解你的边界以及你能控制的和不能控制的东西，对于 API 的数据验证来说是一个很重要的方面。</p><p>最好的策略是在进入数据逻辑处理之前，在你能控制的边界的边缘处进行数据的验证。当客户端向你的 API 发送数据时，你需要对该数据做出任何处理之前应用你的验证，比如：确保 Email 是真实的邮件地址、日期数据有正确的格式、字符串符合长度要求。</p><p>这种简单的检查可以为你的应用增加安全性和一致性。还有，当你从某个服务接收数据时，比如数据库或缓存，你需要重新验证这些数据，以确保返回的结果符合你的数据检查。</p>',9)),t("p",null,[s[31]||(s[31]=l("你可以自己手写这些校验逻辑，当然也可以用像 ",-1)),e(n,{href:"https://lodash.com"},{default:i(()=>[...s[25]||(s[25]=[l("Lodash",-1)])]),_:1}),s[32]||(s[32]=l(" 或 ",-1)),e(n,{href:"https://ramdajs.com/"},{default:i(()=>[...s[26]||(s[26]=[l("Ramda",-1)])]),_:1}),s[33]||(s[33]=l(" 这样的函数库，它们对于一些小的数据对象非常有用。像 ",-1)),e(n,{href:"https://joi.dev/"},{default:i(()=>[...s[27]||(s[27]=[l("Joi",-1)])]),_:1}),s[34]||(s[34]=l("、",-1)),e(n,{href:"https://github.com/jquense/yup"},{default:i(()=>[...s[28]||(s[28]=[l("Yup",-1)])]),_:1}),s[35]||(s[35]=l(" 或 ",-1)),e(n,{href:"https://github.com/colinhacks/zod/tree/v3"},{default:i(()=>[...s[29]||(s[29]=[l("Zod",-1)])]),_:1}),s[36]||(s[36]=l(" 这样的验证库效果会更好，因为它们包含了一些常见的验证方法，可以节省你的时间和精力。除此，它们还能创建一个可读性强的模式。如果你需要看看与语言无关的东西，请看 ",-1)),e(n,{href:"https://json-schema.org/"},{default:i(()=>[...s[30]||(s[30]=[l("JSON Schema",-1)])]),_:1}),s[37]||(s[37]=l("。",-1))]),s[71]||(s[71]=r('<h4 id="总结-2" tabindex="-1">总结 <a class="header-anchor" href="#总结-2" aria-label="Permalink to “总结”">​</a></h4><p>数据验证虽然并不显眼和突出（LCTT 译注：跟 API 的功能实现以及其他几个方面比），但它可以帮你节省大量的时间。如果不做验证，这些时间将可能被用于故障排除和编写数据迁移脚本。真的不要相信你的客户端会发送干净的数据给你，也不要让验证不通过的数据渗入到你的业务逻辑或持久数据存储中去。花点时间验证你的 API 收到的数据和请求到的响应数据，虽然在前期你可能会感到一些挫折和不适，但这总比你在后期花大量时间去做各种数据收紧管制、故障排除等要容易得多。</p><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h3><p>测试是软件开发中的最佳实践，它应该是最主要的非功能性的要求。对于包括 API 在内的任何项目，确定测试策略都是一个挑战，因为你自始至终都要掌握各种约束，以便相应的来制定你的测试策略。</p><p><ruby>集成测试<rt>Integration testing</rt></ruby>是测试 API 的最有效的方法之一。在集成测试模式中，开发团队会创建一个测试集用来覆盖应用流程中的某些部分，从一个点到另一个点。一个好的集成测试流程包括测试 API 的入口点以及模拟请求到服务端的响应。搞定这两点，你就覆盖了整个逻辑，包括从 API 请求的开始到模拟服务器的响应，并返回数据给 API。</p><p>虽然使用的是模拟，但这种方法让能我们专注于代码逻辑层，而不需要去依赖后端服务和展示逻辑来进行测试。没有依赖的测试会更加可靠、更容易实现自动化，且更容易被接入持续集成管道流。</p>',6)),t("p",null,[s[41]||(s[41]=l("集成测试的实施中，我会用 ",-1)),e(n,{href:"https://github.com/substack/tape"},{default:i(()=>[...s[38]||(s[38]=[l("Tape",-1)])]),_:1}),s[42]||(s[42]=l("、",-1)),e(n,{href:"https://github.com/twilson63/test-server"},{default:i(()=>[...s[39]||(s[39]=[l("Test-server",-1)])]),_:1}),s[43]||(s[43]=l(" 和 ",-1)),e(n,{href:"http://www.wheresrhys.co.uk/fetch-mock/"},{default:i(()=>[...s[40]||(s[40]=[l("Fetch-mock",-1)])]),_:1}),s[44]||(s[44]=l("。这些库让我们能够从 API 的请求到数据的响应进行隔离测试，使用 Fetch-mock 还可以将出站请求捕获到持久层。",-1))]),s[72]||(s[72]=t("h4",{id:"总结-3",tabindex:"-1"},[l("总结 "),t("a",{class:"header-anchor",href:"#总结-3","aria-label":"Permalink to “总结”"},"​")],-1)),s[73]||(s[73]=t("p",null,"虽然其他的各种测试和类型检查对 API 也都有很好的益处，但集成测试在流程效率、构建和管理时间方面却有着更大的优势。使用 Fetch-mock 这样的工具，可以在服务边界提供一个干净的模拟场景。",-1)),s[74]||(s[74]=t("h3",{id:"专注于基础",tabindex:"-1"},[l("专注于基础 "),t("a",{class:"header-anchor",href:"#专注于基础","aria-label":"Permalink to “专注于基础”"},"​")],-1)),s[75]||(s[75]=t("p",null,"不管是设计和构建应用程序还是 API，都要确保包含上面的四个基本要素。它们并不是我们唯一需要考虑的非功能性需求，其他的还包括应用监控、日志和 API 管理等。即便如此，安全、文档、验证和测试这四个基本点，对于构建任何使用场景下的完善 API 都是至关重要的关注点。",-1)),s[76]||(s[76]=t("hr",null,null,-1)),t("p",null,[s[46]||(s[46]=l("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/successful-apis"},{default:i(()=>[...s[45]||(s[45]=[l("https://opensource.com/article/21/5/successful-apis",-1)])]),_:1})]),t("p",null,[s[51]||(s[51]=l("作者：",-1)),e(n,{href:"https://opensource.com/users/tomwillson4014"},{default:i(()=>[...s[47]||(s[47]=[l("Tom Wilson",-1)])]),_:1}),s[52]||(s[52]=l(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[48]||(s[48]=[l("lujun9972",-1)])]),_:1}),s[53]||(s[53]=l(" 译者：",-1)),e(n,{href:"https://github.com/ywxgod"},{default:i(()=>[...s[49]||(s[49]=[l("ywxgod",-1)])]),_:1}),s[54]||(s[54]=l(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[50]||(s[50]=[l("wxy",-1)])]),_:1})]),t("p",null,[s[57]||(s[57]=l("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[55]||(s[55]=[l("LCTT",-1)])]),_:1}),s[58]||(s[58]=l(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[56]||(s[56]=[l("Linux中国",-1)])]),_:1}),s[59]||(s[59]=l(" 荣誉推出",-1))])])}const C=a(u,[["render",P]]);export{k as __pageData,C as default};
